int want_type = (int)(*FUZZ_PARAM(unsigned int) & 0x07u);
int cnt = archive_entry_acl_count(entry, want_type);
(void)cnt;
// Validation: simple query with bounded mask; entry preserved.

// Retrieve an opaque pointer to the entry's ACL object; do not dereference.
void *acl = (void*)archive_entry_acl(entry);
(void)acl;
// Validation: opaque pointer may be NULL or non-NULL; no ownership transfer; entry preserved.

// Clear all extended attributes from the entry.
archive_entry_xattr_clear(entry);
// Validation: mutator; entry preserved.

// Add an extended attribute with name and value buffer.
std::string name_s = FUZZ_PARAM_STR(); if (name_s.empty()) { name_s = "user.attr"; }
std::string val_s = FUZZ_PARAM_STR();
// Constrain size to <= 1024 for performance; ensure at least 1 byte.
size_t sz = val_s.size(); if (sz > 1024u) sz = 1024u; if (sz == 0u) { val_s = "\x00"; sz = 1u; }
archive_entry_xattr_add_entry(entry, name_s.c_str(), (const void*)val_s.data(), sz);
// Validation: provided valid name and buffer; entry preserved.

// Return number of extended attributes stored in the entry.
int c = archive_entry_xattr_count(entry);
(void)c;
// Validation: simple query; entry preserved.

// Reset xattr iteration state; subsequent xattr_next() would iterate from the start.
int rc = archive_entry_xattr_reset(entry);
(void)rc;
// Validation: simple state change; entry preserved.

// Parse and add ACL entries from a wide-character text with specified type flags.
// Build a narrow fuzz string and widen it into a bounded std::wstring.
std::string in = FUZZ_PARAM_STR();
if (in.empty()) { in = "u::rwx,g::r-x,o::r--"; }
size_t n = in.size(); if (n > 128u) n = 128u;
std::wstring wtext; wtext.resize(n);
for (size_t i = 0; i < n; ++i) { wtext[i] = (wchar_t)(unsigned char)in[i]; }
int type = (int)(*FUZZ_PARAM(unsigned int) & 0x0Fu); // bound type mask
int rc = archive_entry_acl_from_text_w(entry, wtext.c_str(), type);
(void)rc;
// Validation: provided a valid wide C string and bounded flags; entry remains owned by caller and is returned.

// Iterate over extended attributes; ensure iterator is initialized.
(void)archive_entry_xattr_reset(entry);
const char *name = nullptr; const void *value = nullptr; size_t size = 0;
int rc = archive_entry_xattr_next(entry, &name, &value, &size);
(void)rc; (void)name; (void)value; (void)size;
// Validation: supplied non-NULL output pointers; safe regardless of whether any xattrs exist; entry preserved.

// Clear all sparse file entries from the entry.
archive_entry_sparse_clear(entry);
// Validation: simple mutator; entry preserved for reuse.

// Add a sparse data block with non-negative offset and length.
la_int64_t off = (la_int64_t)(*FUZZ_PARAM(unsigned int) % 2048u);
la_int64_t len = (la_int64_t)(*FUZZ_PARAM(unsigned int) % 2048u);
archive_entry_sparse_add_entry(entry, off, len);
// Validation: offset/length bounded and non-negative; entry preserved.

// Query number of sparse entries present.
int c = archive_entry_sparse_count(entry);
(void)c;
// Validation: read-only query on valid entry; entry preserved.

// Reset sparse entry iteration state.
int rc = archive_entry_sparse_reset(entry);
(void)rc;
// Validation: iterator reset invoked; entry preserved.

// Retrieve the next sparse block; provide valid output pointers.
(void)archive_entry_sparse_reset(entry);
la_int64_t off = 0, len = 0;
int rc = archive_entry_sparse_next(entry, &off, &len);
(void)rc; (void)off; (void)len;
// Validation: non-NULL outputs supplied and iterator initialized; entry preserved.

// Allocate a new link resolver for managing hardlink sets.
struct archive_entry_linkresolver *r = archive_entry_linkresolver_new();
if (!r) { FUZZ_BAIL(); }
void *resolver = (void*)r;
// Track role to validate subsequent operations on this opaque pointer.
FUZZ_SET_ATTR_STR(resolver, "role", "linkresolver");
// Validation: non-NULL resolver created; returned as opaque handle with role attribute.

// Set resolution strategy; ensure correct object role.
int is_lr = !strcmp(FUZZ_GET_ATTR_STR(resolver, "role"), "linkresolver");
if (!is_lr) { FUZZ_BAIL(); }
int format_code = (int)(*FUZZ_PARAM(unsigned int) % 32u); // bounded format code
archive_entry_linkresolver_set_strategy((struct archive_entry_linkresolver*)resolver, format_code);
// Validation: role enforced and bounded strategy code used; resolver returned.

// Free a link resolver; ensure correct role prior to free.
int is_lr = !strcmp(FUZZ_GET_ATTR_STR(resolver, "role"), "linkresolver");
if (!is_lr) { FUZZ_BAIL(); }
archive_entry_linkresolver_free((struct archive_entry_linkresolver*)resolver);
// Validation: freed resolver; not returned to avoid use-after-free.

// Given an entry possibly part of a hardlink set, update and possibly emit a secondary entry.
int is_lr = !strcmp(FUZZ_GET_ATTR_STR(resolver, "role"), "linkresolver");
if (!is_lr) { FUZZ_BAIL(); }
struct archive_entry *e = entry; // caller-provided entry
struct archive_entry *e2 = nullptr; // may be set by linkify when appropriate
archive_entry_linkify((struct archive_entry_linkresolver*)resolver, &e, &e2);
// Return resolver and the (possibly updated) primary entry. We omit e2 from outputs since it may be NULL.
entry = e;
// Validation: enforced resolver role; provided valid entry**/entry** outputs; preserved non-null objects only.

// Retrieve an entry with partial (unseen) links and remaining link count.
int is_lr = !strcmp(FUZZ_GET_ATTR_STR(resolver, "role"), "linkresolver");
if (!is_lr) { FUZZ_BAIL(); }
unsigned int remaining = 0;
struct archive_entry *e = archive_entry_partial_links((struct archive_entry_linkresolver*)resolver, &remaining);
(void)e; (void)remaining; // e may be NULL; do not return possibly-null outputs
// Validation: role enforced; handled possibly-NULL returned entry safely; resolver preserved.

