import random
import string
from typing import List, Tuple

# Libarchive option list string generator
# - Comma-separated options
# - Each option is either:
#   * key
#   * key=value
#   * key! (negation/disable)
# - Keys can be scoped to a module using module:option (e.g., gzip:compression-level=9)
# - Values may be numeric, boolean, keywords, or small strings depending on option
# - Empty string should also be possible (treated as NULL by stubs)
# - Keep total length <= 4096 bytes

MODULE_KEYS = {
    # Filters
    "gzip": {
        "compression-level": list(map(str, range(0, 10))),
        "timestamp": ["0", "1"],
        "mtime": ["0", "1"],
        "rsyncable": ["0", "1", "true", "false"],
        "strategy": ["default", "filtered", "huffman", "rle", "fixed"],
    },
    "bzip2": {
        "compression-level": list(map(str, range(1, 10))),
        "small": ["0", "1", "true", "false"],
        "workfactor": [str(x) for x in range(0, 251, 25)],
    },
    "xz": {
        "compression-level": list(map(str, range(0, 10))),
        "threads": [str(x) for x in range(0, 9)],
        "extreme": ["0", "1", "true", "false"],
        "check": ["crc32", "crc64", "sha256", "none"],
    },
    "lz4": {
        "frame": ["legacy", "modern"],
        "content-size": ["0", "1", "true", "false"],
        "block-checksum": ["0", "1", "true", "false"],
        "block-size": ["64KB", "256KB", "1MB", "4MB"],
    },
    "zstd": {
        "compression-level": [str(x) for x in range(1, 23)],
        "long": ["0", "1", "true", "false"],
        "threads": [str(x) for x in range(0, 9)],
        "checksum": ["0", "1", "true", "false"],
    },
    # Formats
    "zip": {
        "encryption": ["zipcrypt", "aes128", "aes192", "aes256", "none"],
        "experimental": ["0", "1"],
        "zip64": ["0", "1", "auto", "force"],
        "compact": ["0", "1"],
        "hdrcharset": ["UTF-8", "CP932", "KOI8-R", "CP437"],
    },
    "7zip": {
        "solid": ["0", "1"],
        "compression-level": [str(x) for x in range(0, 10)],
        "header-encryption": ["0", "1"],
    },
    "tar": {
        "hdrcharset": ["UTF-8", "en_US.UTF-8", "C", "CP1252"],
        "hdrcharset-binary": ["0", "1"],
        "acls": ["0", "1"],
        "xattrs": ["0", "1"],
        "fflags": ["0", "1"],
        "mac-ext": ["0", "1"],
        "recovery": ["0", "1"],
        "format": ["pax", "ustar", "gnu", "v7"],
        "sparse": ["0", "1"],
    },
    "cpio": {
        "format": ["bin", "odc", "newc", "crc", "posix"],
        "crc": ["0", "1"],
        "mapnumeric": ["0", "1"],
    },
    "mtree": {
        "keyword": ["type", "time", "mode", "uid", "gid", "flags", "size", "link"],
        "indent": ["0", "1"],
        "all": ["0", "1"],
    },
}

# Unscoped common options sometimes supported by both read/write
COMMON_KEYS = {
    "hdrcharset": ["UTF-8", "en_US.UTF-8", "C"],
    "compat-2x": ["0", "1"],
    "warn": ["0", "1"],
    "verbose": ["0", "1", "2"],
}

# Keys that reasonably accept boolean negation with a trailing '!'
NEGATABLE_KEYS = [
    "acls", "xattrs", "fflags", "mac-ext", "recovery", "solid", "crc", "sparse",
    "compact", "experimental", "checksum",
]

ALNUM = string.ascii_letters + string.digits

def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return rng.choice(seq)

def _maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p

def _rand_custom_key(rng: random.Random) -> Tuple[str, str, str]:
    # Occasionally produce unknown but valid-looking custom keys to exercise parser.
    # Format: module:key=value or key=value
    module = None
    if _maybe(rng, 0.5):
        module = _rand_choice(rng, list(MODULE_KEYS.keys()))
    key = ''.join(rng.choice(ALNUM + "_-") for _ in range(rng.randint(3, 10))).lower()
    # Simple values: numeric or small token
    if _maybe(rng, 0.6):
        val = str(rng.randint(0, 100))
    else:
        val = _rand_choice(rng, ["on", "off", "true", "false", "auto", "none"]) \
              if _maybe(rng, 0.7) else ''.join(rng.choice(ALNUM+"._-") for _ in range(rng.randint(2, 8)))
    return (module or "", key, val)

def _build_kv(module: str, key: str, val: str) -> str:
    if module:
        return f"{module}:{key}={val}"
    return f"{key}={val}"

def _build_flag(module: str, key: str) -> str:
    return f"{module}:{key}" if module else key

def _build_neg(module: str, key: str) -> str:
    return (f"{module}:{key}!" if module else f"{key}!")

def _gen_from_catalog(rng: random.Random) -> List[str]:
    opts: List[str] = []
    # Choose 1-3 modules to scope options
    modules = rng.sample(list(MODULE_KEYS.keys()), k=rng.randint(1, min(3, len(MODULE_KEYS))))
    for m in modules:
        keys = list(MODULE_KEYS[m].keys())
        rng.shuffle(keys)
        take = rng.randint(1, min(3, len(keys)))
        for key in keys[:take]:
            values = MODULE_KEYS[m][key]
            if key in NEGATABLE_KEYS and _maybe(rng, 0.25):
                opts.append(_build_neg(m, key))
            elif _maybe(rng, 0.2):
                # Sometimes emit as flag without value
                opts.append(_build_flag(m, key))
            else:
                opts.append(_build_kv(m, key, _rand_choice(rng, values)))
    # Add some unscoped/common options
    ckeys = list(COMMON_KEYS.keys())
    rng.shuffle(ckeys)
    for key in ckeys[:rng.randint(0, min(3, len(ckeys)))]:
        if key in NEGATABLE_KEYS and _maybe(rng, 0.3):
            opts.append(_build_neg("", key))
        elif _maybe(rng, 0.3):
            opts.append(key)
        else:
            opts.append(_build_kv("", key, _rand_choice(rng, COMMON_KEYS[key])))
    return opts

def _gen_simple_presets(rng: random.Random) -> List[str]:
    # Known useful combinations covering readers/writers
    presets = [
        ["gzip:compression-level=9", "tar:format=pax", "tar:acls=1", "tar:xattrs=1"],
        ["xz:compression-level=0", "xz:extreme=1", "tar:format=ustar"],
        ["zip:zip64=auto", "zip:encryption=none", "hdrcharset=UTF-8"],
        ["bzip2:compression-level=7", "cpio:format=newc"],
        ["zstd:compression-level=22", "zstd:checksum=1", "tar:sparse=1"],
        ["lz4:block-size=1MB", "lz4:block-checksum=1", "tar:format=gnu"],
    ]
    return _rand_choice(rng, presets).copy()

def _mix_in_custom(rng: random.Random, opts: List[str]) -> None:
    # Inject a few custom/unknown options to probe option parsing without breaking validity
    for _ in range(rng.randint(0, 3)):
        module, key, val = _rand_custom_key(rng)
        opts.append(_build_kv(module, key, val))

def _maybe_empty_or_null(rng: random.Random) -> bool:
    # Occasionally produce an empty string so the stub passes NULL to libarchive
    return _maybe(rng, 0.08)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    if _maybe_empty_or_null(rng):
        return b""  # empty string => NULL in stubs

    # Choose strategy
    if _maybe(rng, 0.5):
        opts = _gen_from_catalog(rng)
    else:
        opts = _gen_simple_presets(rng)

    # Randomly add extra catalog items for breadth
    if _maybe(rng, 0.5):
        opts.extend(_gen_from_catalog(rng))

    # Mix in a few custom keys to exercise parser paths
    _mix_in_custom(rng, opts)

    # Shuffle and trim to size
    rng.shuffle(opts)

    # Build final string with commas; ensure <= 4096 bytes
    s = ",".join(opts)
    if len(s) > 4096:
        # Trim conservatively
        parts: List[str] = []
        total = 0
        for o in opts:
            if total and total + 1 + len(o) > 4096:
                break
            if total == 0:
                parts.append(o)
                total += len(o)
            else:
                parts.append("," + o)
                total += 1 + len(o)
        s = "".join(parts)

    return s.encode("utf-8")
